<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import SyncSubtreeImpact from './SyncSubtreeImpact.vue';
import SyncResolutionChecks from './SyncResolutionChecks.vue';
import {formatBytes} from './format-bytes';
import {parseResolution,resolutionChoices,resolutionStates,type Resolution} from './sync-resolution';
const props=defineProps<{run:string;ordinal:number;path:string;disabled:boolean;syncActive?:boolean}>(),emit=defineEmits<{authenticationRequired:[];addToBatch:[decision:Resolution]}>();
const open=ref(false),choice=ref('skip'),busy=ref(false),error=ref(''),value=ref<Resolution|null>(null),history=ref<Resolution[]>([]),offset=ref(0),more=ref(false),dialog=ref<HTMLElement>(),launch=ref<HTMLButtonElement>();
let active=true,generation=0,controller:AbortController|undefined;
const current=(n:number)=>active&&n===generation&&open.value;
function invalidate(){generation++;controller?.abort();busy.value=false}
function close(){invalidate();open.value=false;void nextTick(()=>launch.value?.focus())}
function trap(event:KeyboardEvent){const nodes=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),select:not(:disabled),a[href],input:not(:disabled)')||[]);if(!nodes.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialog.value)){event.preventDefault();first.focus()}}
function show(){open.value=true;void nextTick(()=>dialog.value?.focus())}
async function read(url:string,body?:unknown){const n=generation,response=await fetch(url,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:controller?.signal});if(!current(n))throw new DOMException('已离开','AbortError');if(response.status===401){close();emit('authenticationRequired');throw Error('登录已失效')}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'决策读取失败');return response.json()}
async function preview(){if(!active||!open.value||props.disabled||props.syncActive||busy.value)return;const n=++generation;controller=new AbortController();busy.value=true;value.value=null;try{const data=await read('/api/sync/runs/'+props.run+'/resolutions',{ordinal:props.ordinal,choice:choice.value});if(!current(n))return;const parsed=parseResolution(data,props.run,props.ordinal,props.path);if(parsed.choice!==choice.value)throw Error('返回方案与选择不一致');value.value=parsed;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))busy.value=false}}
async function list(at=0){if(!active||!open.value||props.disabled||busy.value)return;const n=++generation;controller=new AbortController();busy.value=true;try{const data=await read('/api/sync/runs/'+props.run+'/resolutions?ordinal='+props.ordinal+'&offset='+at);if(!current(n))return;if(data.source_run!==props.run||data.ordinal!==props.ordinal||data.offset!==at||typeof data.has_more!=='boolean'||!Array.isArray(data.decisions)||data.decisions.length>25||data.has_more&&data.decisions.length!==25)throw Error('决策历史范围无效');history.value=data.decisions.map((r:any)=>parseResolution(r,props.run,props.ordinal,props.path));offset.value=at;more.value=data.has_more;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))busy.value=false}}
function select(r:Resolution){value.value=r;choice.value=r.choice}
function stop(){active=false;close()}
function restore(){active=true}
watch(()=>[props.run,props.ordinal,props.path],()=>{close();value.value=null;history.value=[];error.value='';choice.value='skip';offset.value=0;more.value=false});
watch(()=>props.disabled,v=>{if(v)close()});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><button ref="launch" class="button secondary compact" data-testid="sync-conflict-open" :disabled="disabled" @click="show">处理方案</button><Teleport to="body"><div v-if="open" class="resolution-overlay" @keydown.esc.prevent="close" @keydown.tab="trap"><section ref="dialog" tabindex="-1" role="dialog" aria-modal="true" aria-label="同步冲突处理方案" class="resolution-dialog"><header><div><h2>同步冲突处理方案</h2><p>{{path}}</p></div><button class="button secondary compact" @click="close">关闭</button></header><p class="muted">当前保存历史决策预览，尚未执行。执行前还需重新核对两端；不会按修改时间自动覆盖。</p><p v-if="error" class="notice danger" role="alert">{{error}}</p><form @submit.prevent="preview"><label>处理方案<select v-model="choice" data-testid="sync-conflict-choice" :disabled="busy"><option v-for="(label,key) in resolutionChoices" :key="key" :value="key">{{label}}</option></select></label><button class="button primary" data-testid="sync-conflict-preview" :disabled="busy||disabled||syncActive">{{busy?'正在读取 / 保存…':'保存固定预览'}}</button></form><section v-if="value" data-testid="sync-conflict-result" class="resolution-result"><h3>{{resolutionStates[value.state]}}</h3><p>{{value.note}}</p><p>选择：{{resolutionChoices[value.choice]}} · 方向：{{value.source_config.mode==='pull'?'网盘 → 本地':'双向'}}</p><p>固定决策 {{value.id}}<br>来源冲突 UTC {{value.source_recorded_at_utc}}<br>决策生成 UTC {{value.created_at_utc}}</p><div class="table-wrap"><table><thead><tr><th>来源</th><th>范围 / 项目</th><th>身份 / 大小</th></tr></thead><tbody><tr v-for="side in ['local','remote'] as const" :key="side"><td>{{side==='local'?'本地':'网盘'}}</td><td>{{side==='local'?value.source_config.local_root:value.source_config.remote_root}}<small>{{value.source_conflict.plan[side]?.path||'原快照未见'}}</small></td><td>{{value.source_conflict.plan[side]?.id||'—'}}<small>{{value.source_conflict.plan[side]?.directory?'文件夹':formatBytes(value.source_conflict.plan[side]?.size)}}</small></td></tr></tbody></table></div><p v-if="value.local_copy_path">固定副本路径：{{value.local_copy_path}}</p><table><thead><tr><th>顺序</th><th>位置 / 操作</th><th>原路径 → 目标</th><th>备份</th></tr></thead><tbody><tr v-for="(effect,index) in value.effects" :key="index"><td>{{index+1}}</td><td>{{effect.side==='local'?'本地':'网盘'}} · {{({move:'改名保留',download:'下载网盘版本',upload:'上传本地版本'} as Record<string,string>)[effect.action]}}</td><td>{{effect.from||value.source_conflict.plan.path}} → {{effect.path}}</td><td>{{effect.backup_required?'先备份被替换内容':'无覆盖备份步骤'}}</td></tr><tr v-if="!value.effects.length"><td colspan="4">此决策未安排文件操作。</td></tr></tbody></table><button v-if="value.state==='preview'||value.state==='review_required'&amp;&amp;value.subtree_review?.plan_version==='subtree-steps-v1'&amp;&amp;value.subtree_review.plan_step_count!=='0'" class="button secondary compact" data-testid="sync-batch-add" :disabled="busy||disabled||syncActive" @click="emit('addToBatch',value);close()">加入待处理批次</button><SyncSubtreeImpact v-if="value.subtree_review" :decision="value" :disabled="busy||disabled" @authentication-required="close();emit('authenticationRequired')"/><SyncResolutionChecks :decision="value" :disabled="busy||disabled" :sync-active="syncActive" @authentication-required="close();emit('authenticationRequired')"/><details><summary>来源摘要与完整证据</summary><p>来源快照 UTC {{value.snapshot_recorded_at_utc}} · 事件 {{value.snapshot_event_sequence}}<br>SHA256 {{value.snapshot_evidence_sha256}}</p><pre>{{JSON.stringify(value,null,2)}}</pre></details></section><section><header><h3>本项已保存的决策</h3><button class="button secondary compact" :disabled="busy" @click="list()">读取决策历史</button></header><table v-if="history.length"><thead><tr><th>生成 UTC</th><th>方案 / 状态</th><th>查看</th></tr></thead><tbody><tr v-for="record in history" :key="record.id"><td>{{record.created_at_utc}}</td><td>{{resolutionChoices[record.choice]}}<small>{{resolutionStates[record.state]}}</small></td><td><button class="button secondary compact" :disabled="busy" @click="select(record)">查看固定预览</button></td></tr></tbody></table><footer v-if="history.length"><button class="button secondary compact" :disabled="busy||offset===0" @click="list(Math.max(0,offset-25))">上一页</button><button class="button secondary compact" :disabled="busy||!more" @click="list(offset+25)">下一页</button></footer></section></section></div></Teleport></template>
<style scoped>.resolution-overlay{position:fixed;inset:0;background:#17233b66;z-index:80;display:flex;justify-content:center;align-items:center;padding:20px}.resolution-dialog{background:white;border:1px solid #dbe3ed;border-radius:14px;padding:24px;width:min(920px,100%);max-height:88vh;overflow:auto;box-shadow:0 20px 70px #17233b40;overflow-wrap:anywhere}.resolution-dialog header{display:flex;justify-content:space-between;align-items:center;gap:12px}.resolution-dialog h2,.resolution-dialog h3{margin:8px 0}.resolution-dialog form{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:18px 0}.resolution-dialog label{display:grid;gap:7px}.resolution-dialog select{font:inherit;border:1px solid #cbd5e1;border-radius:7px;padding:8px 10px}.resolution-result{border-top:1px solid #dce4ef;padding-top:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;text-align:left;margin:12px 0}th,td{padding:9px 10px;border-bottom:1px solid #e4eaf2;vertical-align:top}th{background:#f5f7fb}small{display:block;color:#65748b;margin-top:4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}summary{cursor:pointer;color:#245cba}footer{display:flex;gap:8px}@media(max-width:700px){.resolution-dialog{padding:14px}.resolution-overlay{padding:8px}}</style>
